package edu.pe.cibertec.saibm.inventario.infrastructure.persistence; import java.time.Instant; import java.util.*; import jakarta.persistence.*; import edu.pe.cibertec.saibm.inventario.domain.event.InventoryEvent; @Entity @Table(name="inventory_outbox") public class OutboxJpaEntity {@Id UUID eventId;@Column(nullable=false,length=120)String eventType;@Column(nullable=false)int eventVersion;@Column(nullable=false)Instant occurredAt;@Column(nullable=false,length=120)String correlationId;@Column(nullable=false,length=120)String causationId;@Column(nullable=false,length=80)String producer;@Column(nullable=false,columnDefinition="text")String payloadJson;@Column(nullable=false)boolean published;protected OutboxJpaEntity(){}public OutboxJpaEntity(InventoryEvent e,String json){eventId=e.eventId();eventType=e.eventType();eventVersion=e.eventVersion();occurredAt=e.occurredAt();correlationId=e.correlationId();causationId=e.causationId();producer=e.producer();payloadJson=json;published=false;}public UUID getEventId(){return eventId;}public String getEventType(){return eventType;}public String getPayloadJson(){return payloadJson;}public boolean isPublished(){return published;}public void markPublished(){published=true;}}
